// app.js
require('dotenv').config();          // load .env for PORT, NODE_ENV, etc.

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------- Security middleware ----------
app.use(helmet());

app.set('trust proxy', 1); // adjust if behind multiple proxies

// CORS – whitelist via env var (comma‑separated)
const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);
app.use(
  cors({
    origin: allowedOrigins.length ? allowedOrigins : false,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);

// Rate limiting
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Body parsing (JSON only) + size limit
app.use(express.json({ limit: '100kb' }));
app.disable('x-powered-by');

// ---------- Logging ----------
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.use((req, res, next) => {
  logger.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});

// ---------- Helper for async errors ----------
const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

// ---------- Routes ----------
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // In a real app, pull from DB with proper auth / pagination
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  })
);

// Example of a route that *does* accept input – shows validation
app.get(
  '/search',
  [
    query('q')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('query must be between 1‑100 characters')
      .escape(),
  ],
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const term = req.query.q;
    // pretend we search something safely...
    res.json({ term, result: [] });
  })
);

// ---------- 404 handler ----------
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  logger.error(err);
  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
  };
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// ---------- Uncaught exceptions / rejections ----------
process.on('uncaughtException', err => {
  logger.fatal({ err }, 'Uncaught Exception – shutting down');
  process.exit(1);
});
process.on('unhandledRejection', (reason, promise) => {
  logger.fatal({ reason, promise }, 'Unhandled Rejection – shutting down');
  process.exit(1);
});

// ---------- Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

module.exports = app;
```

### What this version adds
1. **Standard security headers** (`helmet`), **CORS whitelist**, **rate limiting**, and **trust‑proxy**.
2. **Unified async error handling** so any future async DB/IO calls are safely caught.
3. **Centralised logging** (via `pino`) and **no exposure of internal stack traces** in production.
4. **Input validation skeleton** (`express-validator`) ready for any new endpoint that takes parameters.
5. **Graceful shutdown on fatal errors** to avoid silent crashes.
6. **Configurable port / environment variables** for flexibility across dev / prod.

