/**
 * Secure & robust version of the demo service.
 * -------------------------------------------------
 * Highlights:
 *   • Helmet for secure HTTP headers
 *   • CORS with an explicit whitelist
 *   • Centralised error handling (no stack traces leaked)
 *   • Async‑handler wrapper to catch Promise rejections
 *   • Input validation skeleton (express‑validator)
 *   • Graceful shutdown on fatal errors
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// -----------------------------------------------------------------
// 1️⃣  Global middleware – security, parsing, limits
// -----------------------------------------------------------------
app.disable('x-powered-by');                // hide framework fingerprint
app.use(helmet());                          // secure HTTP headers

// Adjust the origin list to your own front‑ends / services
const allowedOrigins = [
  'http://localhost:3000',
  // 'https://my-production-domain.com',
];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser tools (e.g., curl, Postman) when origin is undefined
      if (!origin || allowedOrigins.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    maxAge: 86400,
  })
);

// Limit JSON bodies – prevents huge payload attacks
app.use(express.json({ limit: '100kb' }));

// -----------------------------------------------------------------
// 2️⃣  Helper – async wrapper (captures async errors)
// -----------------------------------------------------------------
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// -----------------------------------------------------------------
// 3️⃣  Routes
// -----------------------------------------------------------------
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    // No user input – still wrapped for consistency
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

/**
 * GET /users
 * Example of how you could validate query parameters (e.g., pagination).
 * In this demo we simply return a static list.
 */
app.get(
  '/users',
  // Example validation – uncomment when you actually accept query params
  // query('page')
  //   .optional()
  //   .isInt({ min: 1 })
  //   .toInt()
  //   .withMessage('page must be a positive integer'),
  asyncHandler(async (req, res) => {
    // If you add validators above, check the result here:
    // const errors = validationResult(req);
