    //   return res.status(400).json({ errors: errors.array() });
    // }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// -----------------------------------------------------------------
// 4️⃣  Central error handling (must be after all routes)
// -----------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error – replace console with a proper logger in prod
  console.error(`[${new Date().toISOString()}]`, err);

  // Do not expose stack traces or internal messages to the client
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;

  res.status(status).json({ error: message });
});

// -----------------------------------------------------------------
// 5️⃣  Server bootstrap
// -----------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`✅ Server running on port ${PORT}`);
});

/**
 * Graceful shutdown – useful when the process receives SIGTERM/SIGINT
 * (e.g., container orchestrators, PM2, systemd)
 */
const shutdown = (signal) => {
  console.log(`\n⚡ Received ${signal}. Closing server...`);
  server.close(() => {
    console.log('🛑 Server closed. Exiting process.');
    process.exit(0);
  });
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Catch unhandled promise rejections / exceptions
process.on('unhandledRejection', (reason) => {
  console.error('⚠️ Unhandled Promise Rejection:', reason);
  // In a real app you may want to trigger a graceful shutdown here
});
process.on('uncaughtException', (err) => {
  console.error('💥 Uncaught Exception:', err);
  process.exit(1); // Fatal – better to restart the process
});

module.exports = app;
