require('dotenv').config();                     // Load .env (PORT, NODE_ENV, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const createError = require('http-errors');    // Helper for 4xx/5xx errors

const app = express();

// -------------------------------------------------
// 1️⃣  Global middleware
// -------------------------------------------------
app.use(helmet());                               // Security headers
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
app.use(express.json({ limit: '100kb' }));      // Body parser + size limit
