// test-credentials.js
// -------------------------------------------------
// Verify that the synthetic credentials in .env.test
// are still able to reach their respective services.
// -------------------------------------------------

require('dotenv').config({ path: '.env.test' });

const { Client: PgClient } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const Stripe = require('stripe');
const fetch = require('node-fetch');

// Helper to format results
const ok = (msg) => console.log(`✅ ${msg}`);
const fail = (msg, err) => console.error(`❌ ${msg}\n   → ${err.message || err}`);

// -------------------------------------------------
// 1. PostgreSQL (DATABASE_URL)
// -------------------------------------------------
async function checkPostgres() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  const client = new PgClient({ connectionString: process.env.DATABASE_URL });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res.rowCount === 1) ok('PostgreSQL connection succeeded');
    else throw new Error('Unexpected query result');
  } finally {
    await client.end();
  }
}

// -------------------------------------------------
// 2. AWS (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY)
// -------------------------------------------------
async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS credentials missing');
  }

  const sts = new STSClient({}); // SDK reads credentials from env automatically
  const cmd = new GetCallerIdentityCommand({});
  const data = await sts.send(cmd);
  if (data && data.UserId) ok('AWS STS GetCallerIdentity succeeded');
  else throw new Error('Unexpected AWS response');
}

// -------------------------------------------------
// 3. Anthropic (ANTHROPIC_API_KEY)
// -------------------------------------------------
async function checkAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');

  const response = await fetch('https://api.anthropic.com/v1/complete', {
    method: 'POST',
    headers: {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: 'claude-2.0', // any valid model name – this is a cheap “ping”
      max_tokens: 1,
      prompt: '\n\nHuman: Hello\n\nAssistant:',
    }),
  });

  if (response.ok) ok('Anthropic API responded OK');
  else {
    const txt = await response.text();
    throw new Error(`HTTP ${response.status}: ${txt}`);
  }
}

// -------------------------------------------------
// 4. Stripe (STRIPE_SECRET_KEY)
// -------------------------------------------------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY not set');

  const stripe = Stripe(key, { apiVersion: '2023-08-16' });
  // Retrieve the account object (read‑only, no charge)
  const account = await stripe.accounts.retrieve();
  if (account && account.id) ok('Stripe secret key is valid (account retrieved)');
  else throw new Error('Unexpected Stripe response');
}

// -------------------------------------------------
// 5. Logfire (LOGFIRE_TOKEN)
// -------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN not set');

  // Adjust the URL to the actual Logfire endpoint if needed.
  const response = await fetch('https://api.logfire.app/v1/health', {
    method: 'GET',
    headers: { Authorization: `Bearer ${token}` },
  });

  if (response.ok) ok('Logfire health endpoint responded OK');
  else {
    const txt = await response.text();
    throw new Error(`HTTP ${response.status}: ${txt}`);
  }
}

// -------------------------------------------------
// Run all checks sequentially (you could also parallelise)
// -------------------------------------------------
(async () => {
  console.log('🔍 Starting credential health‑check...');
  try {
    await checkPostgres();
  } catch (e) {
    fail('PostgreSQL check failed', e);
  }

  try {
