// verify-creds.js
// ---------------------------------------------------
// Quick “are these secrets alive?” sanity‑check script.
// ---------------------------------------------------
'use strict';

require('dotenv').config({ path: '.env.test' }); // loads the .env.test file

const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const fetch = require('node-fetch');

async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    console.log('✅ PostgreSQL: OK →', res.rows[0]);
  } catch (err) {
    console.error('❌ PostgreSQL: FAILED', err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY missing');
  }

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1',
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    console.log('✅ AWS STS: OK →', data.Arn);
  } catch (err) {
    console.error('❌ AWS STS: FAILED', err.message);
  }
}

async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('ANTHROPIC_API_KEY missing');

  // The SDK throws on auth errors, so we just catch them.
  const client = new Anthropic({ apiKey: key });

  try {
    // A tiny “ping” – 0‑token message. The API returns a 400 (must have a message) but the **status code** tells us the key is accepted.
    await client.messages.create({
      model: 'claude-3-haiku-20240307',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'Hello' }],
    });
    // If we get here, the request succeeded (unlikely with a canary key).
    console.log('✅ Anthropic: OK (request succeeded)');
  } catch (err) {
    // Anthropic returns a structured error object.
    if (err.status === 401) {
      console.error('❌ Anthropic: INVALID API KEY (401)');
    } else if (err.status === 400) {
      console.log('✅ Anthropic: Key accepted (400 – bad request is expected for the test payload)');
    } else {
      console.error('❌ Anthropic: FAILED', err.message);
    }
  }
}

async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY missing');

  const stripe = new Stripe(key, { apiVersion: '2023-10-16' });

  try {
    const charges = await stripe.charges.list({ limit: 1 });
    console.log('✅ Stripe: OK →', charges?.data?.length ?? 0, 'charges returned');
  } catch (err) {
    // Stripe SDK surfaces a `StripeAuthenticationError` for bad keys.
    if (err.type === 'StripeAuthenticationError') {
      console.error('❌ Stripe: INVALID SECRET KEY');
    } else {
      console.error('❌ Stripe: FAILED', err.message);
    }
  }
}

async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN missing');

  const url = 'https://api.logfire.dev/v1/health';

  try {
    const resp = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!resp.ok) {
      console.error(`❌ Logfire: HTTP ${resp.status}`);
      const body = await resp.text();
      console.error('    response body:', body.trim().slice(0, 200));
      return;
    }
    const data = await resp.json();
    console.log('✅ Logfire: OK →', data);
  } catch (err) {
    console.error('❌ Logfire: FAILED', err.message);
  }
}

// ---------------------------------------------------
// Run all checks in parallel (but isolated so one failure doesn’t abort the others)
// ---------------------------------------------------
(async () => {
  console.log('\n=== Credential sanity‑check ===\n');
  await Promise.allSettled([
    checkPostgres(),
    checkAWS(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
  ]);
  console.log('\n=== Done ===\n');
})();
```

