// scripts/check-creds.js
/*  -------------------------------------------------------------
    Credential‑validation helper
    -------------------------------------------------------------
    • Reads .env.test via dotenv
    • Performs a cheap, read‑only request for each secret
    • Prints PASS / FAIL for every service
    • Exits with code 0 if ALL succeed, otherwise >0
   ------------------------------------------------------------- */

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const { Anthropic } = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const fetch = require('node-fetch');

// Helper to format output
const ok = (msg) => console.log(`✅ ${msg}`);
const fail = (msg, err) =>
  console.error(`❌ ${msg}\n   ↳ ${err?.message || err}`);

// ----------------------------------------------------------------
// 1️⃣ PostgreSQL (DATABASE_URL)
async function checkPostgres() {
  const connStr = process.env.DATABASE_URL;
  if (!connStr) throw new Error('DATABASE_URL not defined');

  const client = new Client({ connectionString: connStr });
  await client.connect();
  const res = await client.query('SELECT 1 as ok');
  await client.end();

  if (res.rows[0].ok !== 1) throw new Error('Unexpected query result');
}
// ----------------------------------------------------------------
// 2️⃣ AWS (access key + secret)
async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY)
    throw new Error('AWS keys missing');

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1',
  });

  await sts.getCallerIdentity().promise(); // resolves if creds are valid
}
// ----------------------------------------------------------------
// 3️⃣ Anthropic
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('ANTHROPIC_API_KEY not defined');

  const client = new Anthropic({ apiKey: key });

  // A minimal request – an empty prompt will be rejected with a
  // “Invalid request” error *only* if the key is wrong.
  await client.messages.create({
    model: 'claude-3-opus-20240229', // any model you have access to
    max_tokens: 1,
    messages: [{ role: 'user', content: '' }],
  });
}
// ----------------------------------------------------------------
// 4️⃣ Stripe
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY not defined');

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });
  // `retrieve` on “account” fetches the connected account tied to the key.
  await stripe.accounts.retrieve();
}
// ----------------------------------------------------------------
// 5️⃣ Logfire (simple ping)
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN not defined');

  // Logfire's public ingestion endpoint – replace with the exact URL
  // documented for your plan if different.
  const url = `https://logfire-api.com/ingest/ping?token=${encodeURIComponent(
    token
  )}`;

  const resp = await fetch(url, { method: 'GET' });
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
}
// ----------------------------------------------------------------

(async () => {
  let failures = 0;

  try {
    await checkPostgres();
    ok('PostgreSQL connection succeeded');
  } catch (e) {
    failures++;
    fail('PostgreSQL connection failed', e);
  }

  try {
    await checkAWS();
    ok('AWS STS credentials succeeded');
  } catch (e) {
    failures++;
    fail('AWS STS credentials failed', e);
  }

  try {
    await checkAnthropic();
    ok('Anthropic API key succeeded');
  } catch (e) {
    failures++;
    fail('Anthropic API key failed', e);
  }

  try {
    await checkStripe();
    ok('Stripe secret key succeeded');
  } catch (e) {
    failures++;
    fail('Stripe secret key failed', e);
  }

  try {
    await checkLogfire();
    ok('Logfire token succeeded');
  } catch (e) {
    failures++;
    fail('Logfire token failed', e);
  }

  // ----------------------------------------------------------------
  if (failures === 0) {
    console.log('\nAll credential checks passed 🎉');
    process.exit(0);
  } else {
    console.error(`\n${failures} check(s) failed`);
    process.exit(1);
  }
})();
```

