  windowMs: 15 * 60 * 1000, // 15‑minute window
  max: 100,                // max 100 requests per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

app.use(morgan('combined'));  // production‑grade request logging
```

