#!/usr/bin/env node
/**
 * verify-creds.js
 *
 * Small helper that attempts to:
 *   • Connect to the PostgreSQL instance described by DATABASE_URL.
 *   • Ping a minimal endpoint of each third‑party API using the supplied keys.
 *
 * It prints a concise pass/fail line for each credential.
