// Helper – console output styling (optional, just for readability)
// ---------------------------------------------------------------------
const ok = (msg) => console.log(`✅ ${msg}`);
const fail = (msg, err) => console.log(`❌ ${msg} – ${err?.message || 'failed'}`);

// ---------------------------------------------------------------------
// 1️⃣  PostgreSQL connectivity test
// ---------------------------------------------------------------------
async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    fail('DATABASE_URL not set');
    return;
  }

  const client = new Client({ connectionString: dbUrl });

  try {
    await client.connect();
    // Run a cheap harmless query
    await client.query('SELECT 1');
    ok('DATABASE_URL – connection succeeded');
  } catch (e) {
    fail('DATABASE_URL – connection failed', e);
  } finally {
    await client.end().catch(() => {}); // ignore possible cleanup errors
  }
}

// ---------------------------------------------------------------------
// 2️⃣  AWS credentials test (simple STS GetCallerIdentity)
// ---------------------------------------------------------------------
async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    fail('AWS credentials not set');
    return;
  }

  const aws = require('aws-sdk');
  // Explicitly configure the SDK with the test keys (no region needed for STS)
  const sts = new aws.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    // In a test environment you may want to set a short timeout
    httpOptions: { timeout: 3000 },
  });

  try {
    await sts.getCallerIdentity().promise();
    ok('AWS credentials – STS GetCallerIdentity succeeded');
  } catch (e) {
    fail('AWS credentials – STS call failed', e);
  }
}

// ---------------------------------------------------------------------
// 3️⃣  Anthropic API key test (ping the models endpoint)
// ---------------------------------------------------------------------
async function testAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    fail('ANTHROPIC_API_KEY not set');
