        headers: {
          'x-api-key': apiKey,
          'content-type': 'application/json',
        },
        timeout: 5000,
      }
    );
    if (resp.status === 200) ok('ANTHROPIC_API_KEY – request succeeded');
    else fail(`ANTHROPIC_API_KEY – unexpected status ${resp.status}`);
  } catch (e) {
    fail('ANTHROPIC_API_KEY – request failed', e);
  }
}

// ---------------------------------------------------------------------
// 4️⃣  Stripe secret key test (retrieve account)
// ---------------------------------------------------------------------
async function testStripe() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    fail('STRIPE_SECRET_KEY not set');
    return;
  }

  const stripe = require('stripe')(stripeKey, { timeout: 5000 });

  try {
    // `retrieve` without an ID returns the current account
    await stripe.accounts.retrieve();
    ok('STRIPE_SECRET_KEY – Stripe API call succeeded');
  } catch (e) {
    fail('STRIPE_SECRET_KEY – Stripe API call failed', e);
  }
}

// ---------------------------------------------------------------------
// 5️⃣  Logfire token test (simple ping if Logfire offers a health endpoint)
// ---------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    fail('LOGFIRE_TOKEN not set');
    return;
  }

  // Replace the URL below with the actual Logfire health endpoint if one exists.
  const url = 'https://logfire.io/api/v1/health';

  try {
    const resp = await axios.get(url, {
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });
    if (resp.status === 200) ok('LOGFIRE_TOKEN – health check succeeded');
    else fail(`LOGFIRE_TOKEN – unexpected status ${resp.status}`);
  } catch (e) {
    fail('LOGFIRE_TOKEN – request failed', e);
  }
}

// ---------------------------------------------------------------------
// Main driver – run all tests in parallel (but wait for completion)
// ---------------------------------------------------------------------
(async () => {
  console.log('🔎 Starting credential verification…\n');

  // Run each test; they return promises, so we can await them all together.
  await Promise.all([
    testDatabase(),
    testAWS(),
    testAnthropic(),
    testStripe(),
    testLogfire(),
  ]);

  console.log('\n✅ Verification complete');
})();
```

