## 2. `verify‑creds.js`

```js
#!/usr/bin/env node
/**
 * verify‑creds.js
 *
 * Small utility that validates the credentials found in .env.test.
 *
 * Usage:
 *   node verify‑creds.js   # or ./verify‑creds.js if you chmod +x
 *
 * The script will:
 *   • Connect to the PostgreSQL database (if DATABASE_URL is set)
 *   • Call AWS STS GetCallerIdentity (if AWS keys are set)
 *   • Ping Anthropic's public model list endpoint (if ANTHROPIC_API_KEY is set)
 *   • List the most recent Stripe charge (if STRIPE_SECRET_KEY is set)
 *   • Ping Logfire (if LOGFIRE_TOKEN is set)
 *
 * Exit code: 0 = all OK, 1 = at least one failure.
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');
const Stripe = require('stripe');
const process = require('process');

async function checkDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) return { name: 'DATABASE_URL', ok: false, error: 'Not defined' };

  const client = new Client({ connectionString: url });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res.rowCount === 1) return { name: 'DATABASE_URL', ok: true };
    else throw new Error('Unexpected query result');
  } catch (e) {
    return { name: 'DATABASE_URL', ok: false, error: e.message };
  } finally {
    await client.end().catch(() => {}); // ignore close errors
  }
}

async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY)
    return { name: 'AWS credentials', ok: false, error: 'Missing keys' };

  const sts = new AWS.STS({ apiVersion: '2011-06-15' });
  try {
    const data = await sts.getCallerIdentity().promise();
    return {
      name: 'AWS STS GetCallerIdentity',
      ok: true,
      details: `ARN=${data.Arn}`,
    };
  } catch (e) {
    return { name: 'AWS STS GetCallerIdentity', ok: false, error: e.message };
  }
}

async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return { name: 'ANTHROPIC_API_KEY', ok: false, error: 'Not defined' };

  try {
    const resp = await axios.get('https://api.anthropic.com/v1/models', {
      headers: { 'x-api-key': key },
      timeout: 8000,
    });
    if (resp.status === 200 && Array.isArray(resp.data.models))
      return { name: 'ANTHROPIC_API_KEY', ok: true };
    else throw new Error('Unexpected response shape');
  } catch (e) {
    return { name: 'ANTHROPIC_API_KEY', ok: false, error: e.message };
  }
}

async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return { name: 'STRIPE_SECRET_KEY', ok: false, error: 'Not defined' };

  const stripe = Stripe(key);
  try {
    // List the most recent charge (read‑only, cheap)
    const charges = await stripe.charges.list({ limit: 1 });
    return { name: 'STRIPE_SECRET_KEY', ok: true, details: `Count=${charges.data.length}` };
  } catch (e) {
    return { name: 'STRIPE_SECRET_KEY', ok: false, error: e.message };
  }
}

async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return { name: 'LOGFIRE_TOKEN', ok: false, error: 'Not defined' };

  // Replace with the real health‑check endpoint if Logfire provides one.
  const url = 'https://api.logfire.io/v1/ping';
  try {
    const resp = await axios.get(url, {
      headers: { Authorization: `Bearer ${token}` },
      timeout: 8000,
    });
    if (resp.status === 200) return { name: 'LOGFIRE_TOKEN', ok: true };
    else throw new Error(`HTTP ${resp.status}`);
  } catch (e) {
    return { name: 'LOGFIRE_TOKEN', ok: false, error: e.message };
  }
}

/* ------------------------------------------------------------------ */
/* Main driver */
(async () => {
  const checks = await Promise.all([
    checkDatabase(),
    checkAWS(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
  ]);

  let allOk = true;
  console.log('\n=== Credential verification report ===\n');
  for (const c of checks) {
    const status = c.ok ? '✅ OK' : `❌ FAIL (${c.error})`;
    const extra = c.details ? ` – ${c.details}` : '';
    console.log(`${c.name}: ${status}${extra}`);
    if (!c.ok) allOk = false;
  }

  console.log('\nSummary:', allOk ? 'All credentials are functional.' : 'One or more checks failed.');
  process.exit(allOk ? 0 : 1);
})();
```

