## 2️⃣  Minimal “drop‑in” rewrite

Below is a **self‑contained patch** that you can apply directly to `app.js`. It introduces:

* Helmet & CORS security headers
* Rate‑limiting middleware
* Centralised async‑error handling (via `express-async-errors`)
* A tiny validation example for a future `GET /users/:id` endpoint (using `express-validator`)
* Environment‑driven port and graceful shutdown
* Structured logging with `morgan`
* A final error‑handler that never leaks stack traces in production

```js
// ------------------------------------------------------------
// app.js – security‑first Express starter
// ------------------------------------------------------------

/* --------------- Dependencies ------------------------------- */
const express = require('express');
require('express-async-errors'); // automatically forwards async throws to error‑handler
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { param, validationResult } = require('express-validator');

/* --------------- App initialization ------------------------ */
const app = express();

/* --------------- Middleware --------------------------------- */
// Security HTTP headers
app.use(helmet());

// CORS – change the whitelist to match your real front‑ends
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser (null) requests like health checks
      if (!origin || allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
  })
);

// Rate limiting – 100 req/min per IP (adjust as needed)
app.use(
  rateLimit({
    windowMs: 60_000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try again later.' },
  })
);

// HTTP request logging (combined format – can be switched to 'tiny' in prod)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parsing – only needed if you later add POST/PUT routes
app.use(express.json());

/* --------------- Routes ------------------------------------- */

/** Health‑check – never throws, no validation needed */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/** Users list – static for demo purposes */
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Example of a parameterised route with validation.
 * In a real app you’d probably pull users from a DB.
 */
app.get(
  '/users/:id',
  // ---- Validation chain -------------------------------------------------
  param('id')
    .trim()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  // ---- Handler -----------------------------------------------------------
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request – safe JSON payload
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = Number(req.params.id);
    const user = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  }
);

/* --------------- Central error handler ----------------------- */
// This must be the *last* middleware added.
app.use((err, req, res, _next) => {
  // Log the error internally – never expose stack traces in prod
  console.error(`[${new Date().toISOString()}] ERROR`, err);

  const status = err.status || 500;
  const payload = {
    error: err.message || 'Internal Server Error',
  };
  // In development you may want the stack trace:
  if (process.env.NODE_ENV !== 'production') {
    payload.stack = err.stack;
  }
  res.status(status).json(payload);
});

/* --------------- Server bootstrap --------------------------- */
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});

/* --------------- Graceful shutdown -------------------------- */
function shutdown(signal) {
  console.log(`\n⚡ Received ${signal} – closing server…`);
  server.close(() => {
    console.log('✅ HTTP server closed.');
    // If you have DB connections, close them here before exiting:
    // db.disconnect(() => process.exit(0));
    process.exit(0);
  });

  // Force quit after 10 seconds if still hanging
  setTimeout(() => {
    console.error('❗ Force‑exiting after timeout.');
    process.exit(1);
  }, 10_000).unref();
}

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('uncaughtException', (err) => {
  console.error('❗ Uncaught Exception:', err);
  shutdown('uncaughtException');
});
process.on('unhandledRejection', (reason) => {
  console.error('❗ Unhandled Rejection:', reason);
  shutdown('unhandledRejection');
});

/* --------------- Export for testing ------------------------ */
module.exports = app;
```

