### `verify_credentials.js`

```js
/**
 * verify_credentials.js
 *
 * Quick “smoke‑test” for the secrets defined in .env.test.
 * • Connects to the PostgreSQL URL (if any) and runs a trivial query.
 * • Calls AWS STS GetCallerIdentity to confirm the AWS keys work.
 * • Sends a minimal request to Anthropic’s API (model list) to validate the key.
 * • Calls Stripe’s /v1/balance endpoint to confirm the Stripe secret.
 * • (Optional) Pings Logfire with the supplied token – you can adjust the URL.
 *
 * The script exits with code 0 when **all checks pass**, otherwise 1.
 */

 // ---------------------------------------------------------------------
// Load environment (optional – only needed if you want to read .env.test)
require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const Stripe = require('stripe');
const fetch = global.fetch; // Node ≥18 provides fetch natively

// ---------------------------------------------------------------------
// Helper – pretty‑print a result line
function report(name, ok, detail = '') {
  const status = ok ? '✅ OK' : '❌ FAIL';
  console.log(`${status} ${name}${detail ? ` – ${detail}` : ''}`);
}

// ---------------------------------------------------------------------
// 1️⃣  PostgreSQL check
async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) {
    report('PostgreSQL', false, 'DATABASE_URL not set');
    return false;
  }

  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    // Run a harmless query – just ask PostgreSQL for the version
    await client.query('SELECT version()');
    report('PostgreSQL', true);
    return true;
  } catch (err) {
    report('PostgreSQL', false, err.message);
    return false;
  } finally {
    await client.end().catch(() => {});
  }
}

// ---------------------------------------------------------------------
// 2️⃣  AWS credentials check (STS GetCallerIdentity)
async function checkAWS() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    report('AWS', false, 'Missing AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY');
    return false;
  }

  const sts = new STSClient({
    credentials: { accessKeyId, secretAccessKey },
    region: 'us-east-1', // any region works for STS
  });

  try {
    await sts.send(new GetCallerIdentityCommand({}));
    report('AWS', true);
    return true;
  } catch (err) {
    report('AWS', false, err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// 3️⃣  Anthropic API key check – request the public model list
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    report('Anthropic', false, 'ANTHROPIC_API_KEY not set');
    return false;
  }

  const url = 'https://api.anthropic.com/v1/models';

  try {
    const resp = await fetch(url, {
      method: 'GET',
      headers: {
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
        accept: 'application/json',
      },
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    // No need to parse body – a 200 means the key is accepted
    report('Anthropic', true);
    return true;
  } catch (err) {
    report('Anthropic', false, err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// 4️⃣  Stripe secret key check – retrieve the account balance
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    report('Stripe', false, 'STRIPE_SECRET_KEY not set');
    return false;
  }

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });

  try {
    // `balance.retrieve()` is a cheap, read‑only call.
    await stripe.balance.retrieve();
    report('Stripe', true);
    return true;
  } catch (err) {
    // Stripe errors have a `code` property (e.g. "invalid_secret_key")
    const msg = err?.code ?? err.message;
    report('Stripe', false, msg);
    return false;
  }
}

// ---------------------------------------------------------------------
// 5️⃣  Logfire token check – make a simple HEAD request.
//    Replace the placeholder URL with the real Logfire endpoint if you have one.
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    report('Logfire', false, 'LOGFIRE_TOKEN not set');
    return false;
  }

  // Example Logfire endpoint (adjust as needed)
  const url = 'https://api.logfire.io/v1/health';

  try {
    const resp = await fetch(url, {
      method: 'HEAD',
      headers: { Authorization: `Bearer ${token}` },
    });

    if (resp.ok) {
      report('Logfire', true);
      return true;
    }
    throw new Error(`HTTP ${resp.status}`);
  } catch (err) {
    report('Logfire', false, err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// Run all checks in parallel, then exit with appropriate code
(async () => {
  const results = await Promise.all([
    checkPostgres(),
    checkAWS(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
  ]);

  const allOk = results.every(Boolean);
  console.log('\n=== Summary ===');
  console.log(allOk ? '✅ All credentials appear valid' : '❌ One or more checks failed');

  // Exit code 0 = success, 1 = failure (useful for CI pipelines)
  process.exit(allOk ? 0 : 1);
})();
```

