  process.exit(1);
}

// ------------------------------------------------------------------
// 3️⃣  POST to the DR endpoint
// ------------------------------------------------------------------
const DR_ENDPOINT = 'http://localhost:47301/api/dr-backup';

(async () => {
  try {
    const resp = await fetch(DR_ENDPOINT, {
