// -------------------------------------------------------------------
// 4️⃣ Stripe – Retrieve account (no money moved)
// -------------------------------------------------------------------
async function checkStripe() {
  const secretKey = process.env.STRIPE_SECRET_KEY;
  if (!secretKey) throw new Error('STRIPE_SECRET_KEY is not defined');

  const stripe = Stripe(secretKey, { apiVersion: '2023-08-16' });
  // The “retrieve account” endpoint returns the account object for the key
  await stripe.accounts.retrieve();
}

