/* -------------------------------------------------
   1️⃣  DATABASE_URL (PostgreSQL)
   ------------------------------------------------- */
async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    fail('DATABASE_URL is not set');
    return;
  }

  const client = new Client({ connectionString: dbUrl, connectionTimeoutMillis: 5000 });

  try {
    await client.connect();
    // Perform a harmless query
    const res = await client.query('SELECT current_timestamp');
    ok(`PostgreSQL connected – server time: ${res.rows[0].current_timestamp}`);
  } catch (err) {
    fail(`PostgreSQL connection failed: ${err.message}`);
  } finally {
    await client.end().catch(() => {}); // ignore errors on close
  }
