  try {
    const resp = await fetch(url, {
      headers: { 'x-api-key': key, 'Content-Type': 'application/json' },
      timeout: 5000,
    });
    if (resp.ok) {
      ok('Anthropic API key is valid (got models list)');
    } else {
      fail(`Anthropic API key rejected – HTTP ${resp.status}`);
    }
  } catch (err) {
    fail(`Anthropic request error: ${err.message}`);
  }
}

/* -------------------------------------------------
   3️⃣  STRIPE_SECRET_KEY – check the “balance” endpoint
   ------------------------------------------------- */
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    fail('STRIPE_SECRET_KEY is not set');
    return;
  }

  const url = 'https://api.stripe.com/v1/balance';
  try {
