   ------------------------------------------------- */
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    fail('LOGFIRE_TOKEN is not set');
    return;
  }

  // Logfire does not expose a public health endpoint, but many services
  // allow a quick GET to the root with the token as a query param.
  // Adjust the URL to whatever “ping” endpoint your Logfire tenant provides.
  const url = `https://logfire.io/api/ping?token=${encodeURIComponent(token)}`;

  try {
    const resp = await fetch(url, { timeout: 5000 });
    if (resp.ok) {
      ok('Logfire token appears valid (ping succeeded)');
    } else {
      fail(`Logfire token rejected – HTTP ${resp.status}`);
    }
  } catch (err) {
    fail(`Logfire request error: ${err.message}`);
  }
}

/* -------------------------------------------------
   5️⃣  AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY – STS GetCallerIdentity
   ------------------------------------------------- */
async function checkAws() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    fail('AWS credentials are not set');
    return;
  }

  const sts = new AWS.STS({
