### `test/credentials‑sanity‑check.js`

```js
#!/usr/bin/env node
/**
 * Quick sanity‑check for the environment variables defined in .env.test.
 *
 * – Validates that DATABASE_URL can be parsed and a single test query succeeds.
 * – Sends a minimal request to each external provider using the supplied API key.
 *
 * Usage:
 *   node test/credentials-sanity-check.js   # runs all checks and prints a summary
 *
 * The script exits with:
 *   0 – all checks passed
 *   1 – one or more checks failed
 *
 * Dependencies (add to your package.json devDependencies):
 *   pg, node-fetch, dotenv
 */

const { Client } = require('pg');
const fetch = require('node-fetch');
require('dotenv').config({ path: '.env.test' }); // <-- points to the test file

// ---------------------------------------------------------------------------
// 1️⃣ Database connectivity test
// ---------------------------------------------------------------------------
async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    throw new Error('DATABASE_URL is not defined');
  }

  const client = new Client({ connectionString: dbUrl, statement_timeout: 5000 });
  try {
    await client.connect();
    // Run an innocuous query – `SELECT 1` works on any PostgreSQL instance
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0]?.ok !== 1) {
      throw new Error('Unexpected query result');
    }
    console.log('✅ DATABASE_URL – connection successful');
  } finally {
    await client.end().catch(() => {}); // ensure we close the client even on error
  }
}

// ---------------------------------------------------------------------------
// 2️⃣ Helper to test an HTTP endpoint with a bearer token
// ---------------------------------------------------------------------------
async function httpCheck({ name, url, tokenHeader, token }) {
  if (!token) {
    throw new Error(`${name}: token not provided`);
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000); // 8‑s timeout

  const response = await fetch(url, {
    method: 'GET',
    headers: { [tokenHeader]: token },
    signal: controller.signal,
  }).finally(() => clearTimeout(timeout));

  if (!response.ok) {
    throw new Error(`${name}: received HTTP ${response.status}`);
  }
  console.log(`✅ ${name} – responded with ${response.status}`);
}

// ---------------------------------------------------------------------------
// 3️⃣ Checks for each external credential
// ---------------------------------------------------------------------------
async function checkAnthropic() {
  // Anthropic provides a public “models” endpoint – we only need a 200 response
  await httpCheck({
    name: 'ANTHROPIC_API_KEY',
    url: 'https://api.anthropic.com/v1/models',
    tokenHeader: 'x-api-key',
    token: process.env.ANTHROPIC_API_KEY,
  });
}

async function checkStripe() {
  // Stripe's “balance” endpoint is cheap and requires no parameters
  await httpCheck({
    name: 'STRIPE_SECRET_KEY',
    url: 'https://api.stripe.com/v1/balance',
    tokenHeader: 'Authorization',
    token: `Bearer ${process.env.STRIPE_SECRET_KEY}`,
  });
}

async function checkLogfire() {
  // Logfire (Logflare) offers a lightweight “ping” endpoint – using the token as a query param
  const token = process.env.LOGFIRE_TOKEN;
  await httpCheck({
    name: 'LOGFIRE_TOKEN',
    url: `https://api.logfire.dev/v1/ping?token=${encodeURIComponent(token)}`,
    tokenHeader: 'Accept', // no auth header needed for the dummy ping
    token: '',
  });
}

// ---------------------------------------------------------------------------
// 4️⃣ Run everything & exit with appropriate status code
// ---------------------------------------------------------------------------
async function runAllChecks() {
  const checks = [
    { fn: checkDatabase, name: 'Database' },
    { fn: checkAnthropic, name: 'Anthropic API' },
    { fn: checkStripe, name: 'Stripe API' },
    { fn: checkLogfire, name: 'Logfire API' },
  ];

  const failures = [];

  for (const { fn, name } of checks) {
    try {
      await fn();
    } catch (err) {
      console.error(`❌ ${name} – ${err.message}`);
      failures.push(name);
    }
  }

  if (failures.length) {
    console.error('\nSummary: some checks failed →', failures.join(', '));
    process.exit(1);
  } else {
    console.log('\nAll credential checks passed ✅');
    process.exit(0);
  }
}

// If the script is executed directly (`node …`), run the checks.
if (require.main === module) {
  runAllChecks();
}

// Export for use in a test runner (e.g., Jest)
module.exports = { runAllChecks };
```

