/**
 * test‑env.js
 *
 * Quick sanity‑check for the credentials defined in .env.test.
 * -----------------------------------------------------------
 *  • PostgreSQL – SELECT 1
 *  • AWS STS   – GetCallerIdentity
 *  • Anthropic – GET /v1/models
 *  • Stripe    – GET /v1/account
