require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch');

// ---------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------
async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: url });
  await client.connect();
  const res = await client.query('SELECT 1');
  await client.end();

  if (!res || !res.rowCount) throw new Error('Unexpected query result');
  return 'PostgreSQL connection OK';
}

async function testAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY missing');
  }

  const sts = new STSClient({});
  const cmd = new GetCallerIdentityCommand({});
  const data = await sts.send(cmd);
  if (!data?.Arn) throw new Error('No ARN returned');
  return `AWS STS works – ARN: ${data.Arn}`;
}

