  if (!key) throw new Error('ANTHROPIC_API_KEY missing');

  const resp = await fetch('https://api.anthropic.com/v1/models', {
    method: 'GET',
    headers: {
      'x-api-key': key,
      'anthropic-version': '2023-06-01',
    },
  });

  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Anthropic API error ${resp.status}: ${txt}`);
  }
  const data = await resp.json();
  return `Anthropic OK – ${data.models?.length ?? 0} models listed`;
}

async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY missing');

  const resp = await fetch('https://api.stripe.com/v1/account', {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${key}`,
    },
  });

  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Stripe API error ${resp.status}: ${txt}`);
  }
  const data = await resp.json();
  return `Stripe OK – account id ${data.id}`;
}

async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN missing');

  // Logfire does not have a public “ping” endpoint documented;
  // most SDKs send data to https://logfire-api.vercel.app/v1/logs.
