  const url = 'https://logfire-api.vercel.app/v1/logs';
  const resp = await fetch(url, {
    method: 'HEAD',
    headers: { Authorization: `Bearer ${token}` },
  });

  if (resp.status === 401) {
    throw new Error('Logfire token rejected (401)');
  }

  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Logfire error ${resp.status}: ${txt}`);
  }

  return 'Logfire token accepted (HEAD 200)';
}

// ---------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------
(async () => {
  const checks = [
    { name: 'PostgreSQL', fn: testPostgres },
    { name: 'AWS STS', fn: testAws },
    { name: 'Anthropic', fn: testAnthropic },
    { name: 'Stripe', fn: testStripe },
    { name: 'Logfire', fn: testLogfire },
  ];

  console.log('\n=== Environment‑credential sanity check ===\n');

  for (const chk of checks) {
    try {
      const msg = await chk.fn();
      console.log(`✅ ${chk.name}: ${msg}`);
    } catch (err) {
      console.error(`❌ ${chk.name}: ${err.message}`);
    }
  }

  console.log('\nDone.\n');
})();
