require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch'); // node >=18 has built‑in fetch; if not, install node-fetch
const Stripe = require('stripe');

// Helper for pretty output
function logResult(name, ok, extra = '') {
  const status = ok ? '✅ PASS' : '❌ FAIL';
  console.log(`${status} ${name} ${extra}`);
}

// ------------------------------------------------------------
// 1️⃣ PostgreSQL connectivity
// ------------------------------------------------------------
async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return logResult('DATABASE_URL', false, '(missing)');
  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    logResult('DATABASE_URL', res.rowCount === 1);
  } catch (e) {
    logResult('DATABASE_URL', false, `(error: ${e.message})`);
  } finally {
    await client.end().catch(() => {});
  }
}

// ------------------------------------------------------------
// 2️⃣ AWS STS GetCallerIdentity (no permissions needed)
// ------------------------------------------------------------
async function checkAws() {
  const id = process.env.AWS_ACCESS_KEY_ID;
  const secret = process.env.AWS_SECRET_ACCESS_KEY;
  if (!id || !secret) return logResult('AWS credentials', false, '(missing)');

  const sts = new AWS.STS({
    accessKeyId: id,
    secretAccessKey: secret,
    // region can be any valid one; STS is global
    region: 'us-east-1',
  });

  try {
    const data = await sts.getCallerIdentity({}).promise();
    logResult('AWS credentials', !!data?.Arn);
  } catch (e) {
    logResult('AWS credentials', false, `(error: ${e.message})`);
  }
}

