 *   • Prints a concise summary and exits with 0 on success, 1 on any failure.
 */

require('dotenv').config({ path: '.env.test' }); // load the test env file

const { Client } = require('pg');
const fetch = require('node-fetch');

// ---------------------------------------------------------------------
// Helper for graceful result printing
// ---------------------------------------------------------------------
function ok(msg) {
  console.log(`✅ ${msg}`);
}
function fail(msg) {
  console.error(`❌ ${msg}`);
}

// ---------------------------------------------------------------------
// 1. PostgreSQL connectivity test
// ---------------------------------------------------------------------
async function testPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) throw new Error('DATABASE_URL not set in environment');

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    // Run a harmless query
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0].ok === 1) {
      ok('PostgreSQL connection succeeded');
    } else {
      fail('PostgreSQL query returned unexpected result');
    }
  } finally {
    await client.end();
  }
}

// ---------------------------------------------------------------------
// 2. Anthropic API health check
// ---------------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('ANTHROPIC_API_KEY not set');

  // Anthropic offers a simple "model list" endpoint that can be used for health checks.
  const url = 'https://api.anthropic.com/v1/models';
  const resp = await fetch(url, {
    headers: {
      'x-api-key': key,
      'anthropic-version': '2023-06-01',
    },
  });

  if (resp.ok) {
    ok('Anthropic API key is valid');
  } else {
    fail(`Anthropic API key test failed – status ${resp.status}`);
  }
}

// ---------------------------------------------------------------------
// 3. Stripe secret key test
// ---------------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY not set');

  // Retrieve the account information (no charge is made)
  const url = 'https://api.stripe.com/v1/account';
  const resp = await fetch(url, {
    headers: {
      Authorization: `Bearer ${key}`,
    },
  });

  if (resp.ok) {
    ok('Stripe secret key is valid');
  } else {
    fail(`Stripe secret key test failed – status ${resp.status}`);
  }
}

// ---------------------------------------------------------------------
// 4. Logfire token test (generic health check)
// ---------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN not set');

  // Logfire (Firecracker) offers a simple /ping endpoint for health checks
  const url = 'https://api.logfire.io/v1/ping';
  const resp = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });

  if (resp.ok) {
    ok('Logfire token is valid');
  } else {
    fail(`Logfire token test failed – status ${resp.status}`);
  }
}

// ---------------------------------------------------------------------
// Main runner
// ---------------------------------------------------------------------
(async () => {
  let hasError = false;
  try {
    await testPostgres();
  } catch (e) {
    hasError = true;
    fail(`PostgreSQL test error: ${e.message}`);
  }

  try {
    await testAnthropic();
  } catch (e) {
    hasError = true;
    fail(`Anthropic test error: ${e.message}`);
  }

  try {
    await testStripe();
  } catch (e) {
    hasError = true;
    fail(`Stripe test error: ${e.message}`);
  }

  try {
    await testLogfire();
  } catch (e) {
    hasError = true;
    fail(`Logfire test error: ${e.message}`);
  }

  process.exit(hasError ? 1 : 0);
})();
